{
  "summary": "Test the backup camera on a 2022 Polestar 2 that repeatedly shows 'Camera Temporarily Unavailable' when reversing on software 3.6.4.",
  "rationale": "The narrative reports the camera-unavailable message almost every time reverse is engaged, persists despite the latest software 3.6.4, and is worse than on prior software; the vehicle also references recall 25V-280. No rulebook entry matches, so the standard backup-camera operation test is appropriate rather than a targeted rulebook test.",
  "group": "adas",
  "symptoms": [
    "Backup camera displays 'Camera Temporarily Unavailable'",
    "Camera unavailable virtually every time the car is put into reverse",
    "Problem worse on latest software 3.6.4"
  ],
  "conditions": [
    "Vehicle put into reverse",
    "Software version 3.6.4 installed",
    "Recall 25V-280 notice received but vehicle stated ineligible"
  ],
  "fault_codes": [],
  "safety_relevant": false,
  "targeted": false,
  "test_name": "",
  "clues": [
    {
      "kind": "symptom",
      "quote": "Camera Temporarily Unavailable"
    },
    {
      "kind": "symptom",
      "quote": "This issue happens virtually every time I put the car into reverse."
    },
    {
      "kind": "condition",
      "quote": "I have the most updated software 3.6.4."
    },
    {
      "kind": "other",
      "quote": "the problem is WORSE with the latest software"
    },
    {
      "kind": "other",
      "quote": "I received a recall notice (25V-280)"
    },
    {
      "kind": "condition",
      "quote": "On prior software versions, the problem existed but was not as pronounced."
    }
  ]
}

